'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8');
let pos = 0;

function nextInt() {
  while (pos < input.length && input.charCodeAt(pos) <= 32) pos++;
  let value = 0;
  while (pos < input.length) {
    const c = input.charCodeAt(pos);
    if (c < 48 || c > 57) break;
    value = value * 10 + c - 48;
    pos++;
  }
  return value;
}

const n = nextInt();
const graph = Array.from({ length: n }, () => []);

for (let i = 0; i < n - 1; i++) {
  const a = nextInt() - 1;
  const b = nextInt() - 1;
  graph[a].push(b);
  graph[b].push(a);
}

const parent = new Int32Array(n).fill(-1);
const order = new Int32Array(n);
let count = 0;

parent[0] = 0;
order[count++] = 0;

for (let i = 0; i < count; i++) {
  const node = order[i];
  for (const next of graph[node]) {
    if (parent[next] === -1) {
      parent[next] = node;
      order[count++] = next;
    }
  }
}

const subtreeSize = new Int32Array(n).fill(1);

for (let i = n - 1; i > 0; i--) {
  const node = order[i];
  subtreeSize[parent[node]] += subtreeSize[node];
}

let answer = n;
for (let i = 1; i < n; i++) {
  const part = subtreeSize[order[i]];
  answer = Math.min(answer, Math.abs(n - 2 * part));
}

console.log(answer);
